insert into public.categories (id,label,sort) values ('preparation','PREPARATION',3) on conflict (id) do update set label=excluded.label, sort=excluded.sort;
insert into public.categories (id,label,sort) values ('intraoperative','INTRAOPERATIVE',4) on conflict (id) do update set label=excluded.label, sort=excluded.sort;
insert into public.categories (id,label,sort) values ('post-anesthesia','POST-ANESTHESIA',5) on conflict (id) do update set label=excluded.label, sort=excluded.sort;
