insert into public.cases (id,number,title,category,difficulty,duration_min,summary,scenario,objectives,patient,vitals,history,"references",scoring,published) values ('pre-anesthesia-assessment',1,'Pre-Anesthesia Assessment','pre-anesthesia','BEGINNER',10,'Assess an elective patient in the pre-operative holding area and pass the key findings to the anesthesia team.','You are the anesthesia nurse in the pre-operative holding area. A patient is scheduled for elective surgery this morning. Complete a structured pre-anesthesia assessment and make sure the anesthesia team knows everything relevant before induction.','["Identify the patient and procedure correctly","Follow a logical pre-anesthesia assessment workflow","Detect safety gaps in a pre-operative checklist","Communicate and document new allergy information"]'::jsonb,'{"sex":"Female","age":38,"procedure":"Elective laparoscopic cholecystectomy","note":"BMI 24, non-smoker"}'::jsonb,'{"bp":"128/78","hr":82,"spo2":98,"temp":36.7,"rr":16}'::jsonb,'["No chronic illness; no regular medication","Previous appendectomy under general anesthesia 10 years ago, no complications reported","Non-smoker, no alcohol","Chart entry from booking: ''No known allergies''"]'::jsonb,'[{"title":"Practice Advisory for Preanesthesia Evaluation","org":"American Society of Anesthesiologists (ASA)"},{"title":"ASA Physical Status Classification System","org":"ASA"},{"title":"Practice Guidelines for Preoperative Fasting","org":"ASA"}]'::jsonb,null,true)
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('pre-anesthesia-assessment','s1',0,'mcq','First contact',null,'The patient has just arrived in the holding area. What do you do FIRST?','Patient Identification',true,false,null,null,'Correct identification and confirmation of the planned procedure prevents wrong-patient and wrong-procedure errors. It comes before any assessment, consent discussion or medication.','Identify the patient and the procedure first. Every other step depends on it.')
insert into public.questions (step_id,payload) select id, '{"options":[{"id":"a","text":"Verify identity with two identifiers and confirm the planned procedure with the patient and the chart"},{"id":"b","text":"Start examining the patient''s airway"},{"id":"c","text":"Ask the patient to sign the consent form straight away"},{"id":"d","text":"Give premedication to reduce anxiety"}],"correct":"a"}'::jsonb from public.case_steps where case_id='pre-anesthesia-assessment' and step_key='s1'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('pre-anesthesia-assessment','s2',1,'sequence','Assessment workflow',null,'Arrange the pre-anesthesia assessment in a logical order.','Patient Assessment',false,false,null,null,'History guides what to look for on examination, and both guide which investigations are relevant. Consent is confirmed once the plan is clear, and the findings are recorded and communicated last. Institutions may vary slightly; this station follows a history, examination, investigations, consent, communication flow.','History first, examination second, then investigations, consent and communication.')
insert into public.questions (step_id,payload) select id, '{"items":[{"id":"i1","text":"Review medical, surgical and previous anesthesia history"},{"id":"i2","text":"Confirm allergies, current medication and other safety questions"},{"id":"i3","text":"Perform a focused physical examination, including the airway"},{"id":"i4","text":"Review relevant investigations"},{"id":"i5","text":"Confirm informed consent is documented and understood"},{"id":"i6","text":"Record the assessment and communicate findings to the anesthesia team"}]}'::jsonb from public.case_steps where case_id='pre-anesthesia-assessment' and step_key='s2'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('pre-anesthesia-assessment','s3',2,'find-error','Checklist review',null,'Review the pre-operative checklist below. Which entries need to be corrected before the patient goes to the operating room?','Safety',true,false,null,null,'Two entries are unsafe: fasting time that does not meet common guidance was marked adequate, and the allergy section was left blank. Both can lead to serious harm if not corrected before induction.','Never accept a checklist item as done unless it is verified and consistent with the facts.')
insert into public.questions (step_id,payload) select id, '{"instruction":"Select every entry that is incorrect or unsafe.","items":[{"id":"c1","label":"Identity band matches chart: name and date of birth checked","correct":false,"why":"Appropriate identity check."},{"id":"c2","label":"Planned procedure on the consent form matches the operating list","correct":false,"why":"Consent and list agree."},{"id":"c3","label":"Fasting: last solid meal 4 hours ago, marked ''adequate, proceed''","correct":true,"why":"Common ASA fasting guidance is at least 6 hours after a light meal and longer after a fatty meal. 4 hours is not adequate; the anesthesiologist must be told."},{"id":"c4","label":"Current medication: none, recorded","correct":false,"why":"Recorded correctly."},{"id":"c5","label":"Allergy section: left blank (''will ask later'')","correct":true,"why":"Allergy status must be actively confirmed and recorded before anesthesia, never left blank."},{"id":"c6","label":"Baseline vital signs measured and recorded","correct":false,"why":"Baseline values are documented."}]}'::jsonb from public.case_steps where case_id='pre-anesthesia-assessment' and step_key='s3'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('pre-anesthesia-assessment','s4',3,'branching','New allergy information','While you review the history, the patient tells you she had itching and a skin rash after taking amoxicillin as a child. The chart still says ''No known allergies''.','What is the most appropriate action?','Communication',true,false,null,'["Patient reports rash and itching after amoxicillin (childhood)"]'::jsonb,'Any reported drug reaction must be clarified, documented and communicated. Even a reaction that seems minor changes which drugs the team will choose.','Reported allergy means clarify, document and communicate. All three.')
insert into public.questions (step_id,payload) select id, '{"options":[{"id":"a","text":"Clarify the details (drug, reaction, timing), document it as a reported allergy and inform the anesthesia team before the case","score":100,"consequence":"The allergy is documented and flagged. The anesthesia team can take it into account when planning drugs for the case."},{"id":"b","text":"Write it in the notes but tell nobody, because the chart is already signed","score":40,"consequence":"It is documented, but the team may not see it in time. Documentation without communication leaves a gap."},{"id":"c","text":"Ignore it: a rash in childhood is unlikely to matter","score":0,"consequence":"The reaction stays unrecorded and the team is unaware of it.","remedial":"r1"},{"id":"d","text":"Wait to see whether the surgeon asks about allergies","score":0,"consequence":"Nobody may ask, and the information stays with you.","remedial":"r1"}]}'::jsonb from public.case_steps where case_id='pre-anesthesia-assessment' and step_key='s4'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('pre-anesthesia-assessment','r1',4,'mcq','Follow-up: antibiotic prophylaxis','The team is now preparing routine antibiotic prophylaxis. The chart still reads ''No known allergies''.','You remember what the patient told you. What do you do now?','Communication',false,true,null,null,'Every team member is responsible for speaking up when patient safety information conflicts with the chart. The right moment is before the drug is given.','If you know something that affects safety, speak up before the action, not after.')
insert into public.questions (step_id,payload) select id, '{"options":[{"id":"a","text":"Speak up immediately: tell the anesthesiologist about the reported reaction so it can be verified before any antibiotic is given"},{"id":"b","text":"Stay quiet, because it is not your responsibility"},{"id":"c","text":"Wait until the surgeon has finished"},{"id":"d","text":"Give the antibiotic slowly and watch the patient"}],"correct":"a"}'::jsonb from public.case_steps where case_id='pre-anesthesia-assessment' and step_key='r1'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('pre-anesthesia-assessment','s5',5,'mcq','Investigations',null,'This patient is generally healthy with no chronic disease. Which statement about pre-operative investigations is most appropriate?','Critical Thinking',false,false,null,null,'Current practice advisories support selective, indication-based testing guided by the history, examination and type of surgery. Routine testing in healthy patients adds cost and false alarms without clear benefit.','Order and review tests for a reason, not by habit.')
insert into public.questions (step_id,payload) select id, '{"options":[{"id":"a","text":"Tests should be selected based on the patient''s clinical condition and the planned surgery, not ordered routinely for everyone"},{"id":"b","text":"Every patient needs a full panel of blood tests, chest X-ray and ECG"},{"id":"c","text":"No investigation is ever needed before surgery"},{"id":"d","text":"Only the surgeon decides which tests are relevant"}],"correct":"a"}'::jsonb from public.case_steps where case_id='pre-anesthesia-assessment' and step_key='s5'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('pre-anesthesia-assessment','s6',6,'mcq','ASA class','Summary: 38 years old, BMI 24, non-smoker, no systemic disease, no regular medication, planned elective laparoscopic cholecystectomy.','Which ASA Physical Status class fits this patient best?','Patient Assessment',false,false,null,null,'A healthy, non-smoking patient without systemic disease is ASA I. The final class is assigned by the anesthesiologist; your role is to give accurate information for that decision.','ASA class reflects systemic health, not the planned operation.')
insert into public.questions (step_id,payload) select id, '{"options":[{"id":"a","text":"ASA I: a normal healthy patient"},{"id":"b","text":"ASA II: a patient with mild systemic disease"},{"id":"c","text":"ASA III: a patient with severe systemic disease"},{"id":"d","text":"ASA IV: severe systemic disease that is a constant threat to life"}],"correct":"a"}'::jsonb from public.case_steps where case_id='pre-anesthesia-assessment' and step_key='s6'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('pre-anesthesia-assessment','s7',7,'mcq','Documentation',null,'Which entry best reflects good documentation of this pre-anesthesia assessment?','Documentation',false,false,null,null,'The record is the shared source of truth for the whole team. It must be accurate, complete, legible, timed and signed for this patient. Copying another entry risks serious errors.','If it is not documented, the next person cannot rely on it.')
insert into public.questions (step_id,payload) select id, '{"options":[{"id":"a","text":"A legible, timed and signed record covering history, allergies, fasting status, airway findings, ASA class and what was communicated to the team"},{"id":"b","text":"A verbal report is enough; writing can wait until after the case"},{"id":"c","text":"Only vital signs, because the rest is in the surgeon''s notes"},{"id":"d","text":"Copy another patient''s entry and change the name"}],"correct":"a"}'::jsonb from public.case_steps where case_id='pre-anesthesia-assessment' and step_key='s7'
insert into public.cases (id,number,title,category,difficulty,duration_min,summary,scenario,objectives,patient,vitals,history,"references",scoring,published) values ('airway-management',2,'Airway Assessment and Preparation','airway','INTERMEDIATE',12,'Recognise features of a potentially difficult airway and prepare equipment and steps for a safe intubation.','You are assisting the anesthesiologist before general anesthesia. Your task is to recognise airway risk, prepare the equipment, support the intubation sequence and respond correctly when confirmation of tube placement fails.','["Recognise findings that predict a difficult airway","Prepare primary and backup airway equipment","Follow a safe airway preparation sequence","Respond to absent capnography after intubation"]'::jsonb,'{"sex":"Male","age":52,"procedure":"Elective hernia repair under general anesthesia","note":"BMI 34"}'::jsonb,'{"bp":"134/84","hr":78,"spo2":97,"temp":36.8,"rr":16}'::jsonb,'["BMI 34, snores at night","Full beard","No known allergies","No previous anesthesia problems reported"]'::jsonb,'[{"title":"Practice Guidelines for Management of the Difficult Airway","org":"American Society of Anesthesiologists (ASA)"},{"title":"Standards for Basic Anesthetic Monitoring","org":"ASA"}]'::jsonb,null,true)
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('airway-management','s1',0,'equipment','Airway examination',null,'The examination findings are listed below. Which ones raise concern?','Airway Assessment',true,false,null,null,'Mallampati III, short thyromental distance, limited neck extension and a full beard are recognised risk indicators for difficult laryngoscopy or mask ventilation. Adequate mouth opening and intact teeth are not concerns.','Look for combinations of risk indicators, not a single sign.')
insert into public.questions (step_id,payload) select id, '{"instruction":"Select ALL findings that suggest a potentially difficult airway.","items":[{"id":"f1","label":"Mallampati class III","correct":true,"why":"Poor visualisation of oropharyngeal structures can predict difficult laryngoscopy."},{"id":"f2","label":"Thyromental distance about 5 cm","correct":true,"why":"A short thyromental distance can predict a more anterior larynx and difficult view."},{"id":"f3","label":"Limited neck extension","correct":true,"why":"Limited extension makes it harder to align the airway axes."},{"id":"f4","label":"Full beard","correct":true,"why":"A beard can prevent a good mask seal during bag-mask ventilation."},{"id":"f5","label":"Mouth opening about 4 cm","correct":false,"why":"Adequate mouth opening; not a risk factor."},{"id":"f6","label":"Intact natural teeth, none loose","correct":false,"why":"Normal dentition is not a risk indicator."}]}'::jsonb from public.case_steps where case_id='airway-management' and step_key='s1'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('airway-management','s2',1,'mcq','Planning','You have identified several risk indicators for a difficult airway.','What is the most appropriate response?','Airway Management',true,false,null,null,'Difficult airway guidelines stress recognising the problem early and having a strategy and backup devices prepared before induction. The plan is made by the anesthesiologist with the team.','Anticipate, communicate and prepare before induction.')
insert into public.questions (step_id,payload) select id, '{"options":[{"id":"a","text":"Tell the anesthesiologist about the findings and make sure backup airway equipment is ready before induction"},{"id":"b","text":"Proceed as routine and deal with problems only if they appear"},{"id":"c","text":"Cancel the operation yourself"},{"id":"d","text":"Decide the airway plan after the patient is asleep"}],"correct":"a"}'::jsonb from public.case_steps where case_id='airway-management' and step_key='s2'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('airway-management','s3',2,'equipment','Prepare the airway station',null,'Which items belong in the airway set-up for this patient?','Equipment Preparation',true,false,null,null,'The set-up includes suction, ventilation equipment, primary intubation devices in several sizes, backups such as a supraglottic airway and a video laryngoscope, and capnography. Items for other procedures are not needed.','Prepare primary AND backup devices, and test them before induction.')
insert into public.questions (step_id,payload) select id, '{"instruction":"Select the equipment that should be prepared for this induction.","items":[{"id":"e1","label":"Suction unit with rigid catheter, tested","correct":true,"why":"Suction must be working before induction."},{"id":"e2","label":"Bag-mask with oxygen source and well-fitting face masks","correct":true,"why":"Needed for pre-oxygenation and rescue ventilation."},{"id":"e3","label":"Laryngoscope handle and blades, light checked","correct":true,"why":"A failed light is a preventable problem."},{"id":"e4","label":"Endotracheal tubes: intended size plus one smaller and one larger, cuff tested","correct":true,"why":"Sizes vary; the cuff must be tested before use."},{"id":"e5","label":"Stylet or bougie","correct":true,"why":"Helps with a difficult view."},{"id":"e6","label":"Supraglottic airway as a backup device","correct":true,"why":"A standard backup when intubation or mask ventilation is difficult."},{"id":"e7","label":"Video laryngoscope available in the room","correct":true,"why":"Useful when difficulty is anticipated."},{"id":"e8","label":"Waveform capnography connected","correct":true,"why":"Needed to confirm tube position."},{"id":"e9","label":"Chest drain kit","correct":false,"why":"Not part of routine airway set-up."},{"id":"e10","label":"Urinary catheter set","correct":false,"why":"Unrelated to airway management."},{"id":"e11","label":"Arterial line kit","correct":false,"why":"Not needed for airway management in this patient."},{"id":"e12","label":"Defibrillator pads applied to the patient","correct":false,"why":"Defibrillator should be accessible, but pads are not applied for routine induction."}]}'::jsonb from public.case_steps where case_id='airway-management' and step_key='s3'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('airway-management','s4',3,'sequence','Intubation sequence',null,'Arrange the steps around intubation in a safe order.','Airway Management',false,false,null,null,'Equipment is checked first, then the patient is positioned and pre-oxygenated. Only then does induction and intubation happen, followed by confirmation of placement and securing the tube.','Check, position, pre-oxygenate, intubate, confirm, secure.')
insert into public.questions (step_id,payload) select id, '{"items":[{"id":"i1","text":"Check suction, laryngoscope light, tube cuff and bag-mask circuit"},{"id":"i2","text":"Position the patient for laryngoscopy"},{"id":"i3","text":"Pre-oxygenate with a well-fitted face mask"},{"id":"i4","text":"Assist the anesthesiologist with induction and tube placement"},{"id":"i5","text":"Confirm tube position: waveform capnography, chest movement, auscultation"},{"id":"i6","text":"Secure the tube and record its depth"}]}'::jsonb from public.case_steps where case_id='airway-management' and step_key='s4'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('airway-management','s5',4,'branching','No CO₂ waveform','The tube has been placed and connected to the circuit. The capnography shows NO waveform. Chest rise is unclear and SpO₂ is starting to fall.','What do you do?','Emergency Response',true,false,'{"spo2":95,"hr":88}'::jsonb,null,'Absent end-tidal CO₂ after intubation means the tube must be assumed misplaced, or the circuit disconnected or obstructed, until proven otherwise. Waveform capnography is the most reliable confirmation of tracheal placement. Report at once and keep the patient oxygenated.','No waveform means no confirmation. Report immediately and keep oxygenating.')
insert into public.questions (step_id,payload) select id, '{"options":[{"id":"a","text":"Tell the anesthesiologist immediately that there is no CO₂ waveform, keep oxygenating and help re-check tube position as directed","score":100,"consequence":"The anesthesiologist knows at once and can reassess the airway while oxygenation is maintained."},{"id":"b","text":"Check the sampling line and connections yourself and report only if the problem persists","score":40,"consequence":"Checking connections is sensible, but delaying the report is unsafe when the airway may be misplaced."},{"id":"c","text":"Rely on chest auscultation and continue, because capnography is only a backup","score":0,"consequence":"Auscultation alone can be misleading. The tube may not be in the trachea and the patient is now desaturating.","remedial":"r1"},{"id":"d","text":"Secure the tube with tape and wait a few minutes to see if CO₂ appears","score":0,"consequence":"Waiting delays recognition of a possible misplaced tube while oxygen levels fall.","remedial":"r1"}]}'::jsonb from public.case_steps where case_id='airway-management' and step_key='s5'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('airway-management','r1',5,'mcq','Follow-up: falling SpO₂','SpO₂ is now 88% and still falling. The capnography waveform is still absent.','What is the priority now?','Emergency Response',false,true,'{"spo2":88,"hr":104}'::jsonb,null,'A falling SpO₂ with no confirmation of ventilation is an emergency. Calling for help early and supporting oxygenation is the priority.','Falling SpO₂ plus unconfirmed airway: call for help early.')
insert into public.questions (step_id,payload) select id, '{"options":[{"id":"a","text":"Call for urgent help, alert the anesthesiologist and support oxygenation while tube position is re-evaluated"},{"id":"b","text":"Wait for the SpO₂ to recover on its own"},{"id":"c","text":"Record the values and carry on preparing the drapes"},{"id":"d","text":"Ask the surgeon to start so time is not wasted"}],"correct":"a"}'::jsonb from public.case_steps where case_id='airway-management' and step_key='r1'
insert into public.cases (id,number,title,category,difficulty,duration_min,summary,scenario,objectives,patient,vitals,history,"references",scoring,published) values ('before-induction-safety-check',3,'Before Induction Safety Check','preparation','INTERMEDIATE',10,'Run the Sign In phase and the equipment check before anesthesia, and stop the case when a safety check fails.','The patient is in the operating room and awake. Before induction, the team performs the Sign In phase of the surgical safety checklist and the anesthesia machine and equipment check. You are the anesthesia nurse responsible for making sure nothing is skipped.','["Place the Sign In phase in the surgical safety checklist","Recall the order of Sign In items","Detect unsafe entries on the checklist","Verify machine and equipment, and respond to a failed check"]'::jsonb,'{"sex":"Male","age":45,"procedure":"Elective left knee arthroscopy under general anesthesia","note":"ASA I"}'::jsonb,'{"bp":"126/80","hr":74,"spo2":99,"temp":36.6,"rr":14}'::jsonb,'["No chronic illness, no regular medication","Reports itchy skin after wearing latex gloves","Planned procedure: LEFT knee","Fasting confirmed by patient"]'::jsonb,'[{"title":"WHO Surgical Safety Checklist","org":"World Health Organization (WHO)"},{"title":"Pre-Anesthesia Checkout Procedures (anesthesia machine)","org":"ASA / manufacturer instructions"}]'::jsonb,null,true)
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('before-induction-safety-check','s1',0,'mcq','Which phase?','The patient is in the operating room, awake, and induction has not started.','Which phase of the WHO Surgical Safety Checklist applies now?','Safety',false,false,null,null,'The Sign In phase takes place before induction of anesthesia. Time Out is before incision and Sign Out is before the patient leaves the room.','Sign In = before induction. Time Out = before incision. Sign Out = before leaving.')
insert into public.questions (step_id,payload) select id, '{"options":[{"id":"a","text":"Sign In (before induction of anesthesia)"},{"id":"b","text":"Time Out (before skin incision)"},{"id":"c","text":"Sign Out (before the patient leaves the operating room)"},{"id":"d","text":"Pre-operative clinic visit"}],"correct":"a"}'::jsonb from public.case_steps where case_id='before-induction-safety-check' and step_key='s1'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('before-induction-safety-check','s2',1,'sequence','Sign In order',null,'Arrange the Sign In items in the order they appear on the WHO checklist.','Safety',false,false,null,null,'The WHO Sign In section starts with identity, site, procedure and consent, then site marking, the anesthesia safety check, pulse oximeter, allergy, and difficult airway or aspiration risk.','Learn the checklist order so no item is skipped under pressure.')
insert into public.questions (step_id,payload) select id, '{"items":[{"id":"i1","text":"Confirm identity, site, procedure and consent"},{"id":"i2","text":"Confirm the surgical site is marked"},{"id":"i3","text":"Confirm the anesthesia safety check is complete"},{"id":"i4","text":"Confirm the pulse oximeter is on the patient and working"},{"id":"i5","text":"Ask about known allergy"},{"id":"i6","text":"Assess difficult airway or aspiration risk"}]}'::jsonb from public.case_steps where case_id='before-induction-safety-check' and step_key='s2'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('before-induction-safety-check','s3',2,'find-error','Spot the unsafe entries',null,'The team has ticked the following Sign In items. Which entries must be corrected before induction?','Safety',true,false,null,null,'Two entries are unsafe: the site was not marked while the patient was awake, and the allergy entry contradicts the history. Both must be fixed before induction.','A ticked box is only safe when it matches the facts.')
insert into public.questions (step_id,payload) select id, '{"instruction":"Select every entry that is incorrect or unsafe.","items":[{"id":"c1","label":"Patient confirmed identity, site, procedure and consent","correct":false,"why":"Correct confirmation."},{"id":"c2","label":"Site marking: left knee not marked (''will mark after induction'')","correct":true,"why":"The site must be marked while the patient is awake and can confirm it."},{"id":"c3","label":"Pulse oximeter on the patient and functioning","correct":false,"why":"Correct."},{"id":"c4","label":"Allergy: ''No known allergy'' ticked, although the patient reported itching with latex gloves","correct":true,"why":"A reported latex reaction contradicts the ticked entry and must be clarified and communicated."},{"id":"c5","label":"Anesthesia safety check (machine and medication) completed","correct":false,"why":"Correct."},{"id":"c6","label":"Difficult airway and aspiration risk assessed, equipment available","correct":false,"why":"Correct."}]}'::jsonb from public.case_steps where case_id='before-induction-safety-check' and step_key='s3'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('before-induction-safety-check','s4',3,'equipment','Machine and equipment check',null,'Which items belong to the anesthesia machine and equipment check?','Equipment Preparation',true,false,null,null,'The pre-use check covers oxygen supply and backup, leak test, backup ventilation, suction, monitor alarms and scavenging. Surgical instrument counts, bed assignment and sutures belong to other checks.','Check what keeps the patient oxygenated, ventilated and monitored.')
insert into public.questions (step_id,payload) select id, '{"instruction":"Select the items that must be verified before induction.","items":[{"id":"e1","label":"Oxygen supply connected and backup oxygen cylinder available","correct":true,"why":"Loss of oxygen supply must be covered by a backup."},{"id":"e2","label":"Breathing circuit leak test performed","correct":true,"why":"Detects leaks and disconnections."},{"id":"e3","label":"Self-inflating resuscitation bag ready","correct":true,"why":"Independent backup for ventilation."},{"id":"e4","label":"Suction working","correct":true,"why":"Needed before induction."},{"id":"e5","label":"Monitor alarms audible and limits appropriate","correct":true,"why":"Alarms only help when they are on and set correctly."},{"id":"e6","label":"Gas scavenging system connected","correct":true,"why":"Protects staff from waste anesthetic gas."},{"id":"e7","label":"Surgical instrument count sheet","correct":false,"why":"A surgical team task, not part of the machine check."},{"id":"e8","label":"Post-operative bed assignment","correct":false,"why":"Not part of the machine check."},{"id":"e9","label":"Suture selection for wound closure","correct":false,"why":"A surgical preparation task."}]}'::jsonb from public.case_steps where case_id='before-induction-safety-check' and step_key='s4'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('before-induction-safety-check','s5',4,'branching','Failed leak test','During the circuit leak test the pressure will not hold. You suspect a loose connection but have not found it. The team is waiting.','What should you do?','Equipment Preparation',true,false,null,null,'A failed pre-use check means the machine is not ready. Fix or replace the equipment, repeat the check and inform the anesthesiologist before induction.','A failed check stops the case until it passes.')
insert into public.questions (step_id,payload) select id, '{"options":[{"id":"a","text":"Do not proceed to induction. Recheck connections or replace the circuit or machine, repeat the check and inform the anesthesiologist","score":100,"consequence":"Induction is delayed until the equipment is confirmed safe, and the anesthesiologist is informed."},{"id":"b","text":"Proceed, because a small leak can be compensated with higher fresh gas flow","score":0,"consequence":"Starting with a known leak risks inadequate ventilation and delivery of gas to the patient.","remedial":"r1"},{"id":"c","text":"Recheck all connections and retest, but tell nobody until it is fixed","score":40,"consequence":"Rechecking is right, but the anesthesiologist must be told that the check failed."},{"id":"d","text":"Skip the leak test, because the machine passed its checks yesterday","score":0,"consequence":"The pre-use check must be done before each case.","remedial":"r1"}]}'::jsonb from public.case_steps where case_id='before-induction-safety-check' and step_key='s5'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('before-induction-safety-check','r1',5,'mcq','Follow-up: replacement circuit','A replacement breathing circuit has been fitted.','What must happen before the machine is used?','Equipment Preparation',false,true,null,null,'Any change to the breathing system requires the checks to be repeated. Visual inspection alone cannot detect a leak.','Change the equipment, repeat the check.')
insert into public.questions (step_id,payload) select id, '{"options":[{"id":"a","text":"Repeat the leak test and relevant checks on the new set-up, and confirm the result to the anesthesiologist"},{"id":"b","text":"Nothing: a new circuit is always safe"},{"id":"c","text":"Only check that the circuit looks intact"},{"id":"d","text":"Test it after induction has begun"}],"correct":"a"}'::jsonb from public.case_steps where case_id='before-induction-safety-check' and step_key='r1'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('before-induction-safety-check','s6',6,'mcq','Medication labelling','Syringes of anesthetic medication have been drawn up by the team and are on the tray.','What must be true before any medication is given?','Medication Safety',true,false,null,null,'Unlabelled syringes are a major source of medication errors. Each syringe must be labelled and verified before it is given.','Label everything, verify before giving.')
insert into public.questions (step_id,payload) select id, '{"options":[{"id":"a","text":"Every syringe is clearly labelled (drug name, concentration) and verified before administration"},{"id":"b","text":"Unlabelled syringes are acceptable if used immediately"},{"id":"c","text":"Only the first syringe needs a label"},{"id":"d","text":"Labels can be added after the case"}],"correct":"a"}'::jsonb from public.case_steps where case_id='before-induction-safety-check' and step_key='s6'
insert into public.cases (id,number,title,category,difficulty,duration_min,summary,scenario,objectives,patient,vitals,history,"references",scoring,published) values ('perioperative-monitoring',4,'Perioperative Monitoring','monitoring','BEGINNER',9,'Set up basic monitoring, spot monitoring errors and react to a change in the patient''s blood pressure.','You are preparing the monitoring for a patient scheduled for general anesthesia. Choose and check the monitors, interpret what you see, and respond correctly when the vital signs change during surgery.','["Name the basic monitoring standard for general anesthesia","Prepare the correct monitoring equipment","Detect monitoring set-up errors","React to a change in vital signs"]'::jsonb,'{"sex":"Female","age":29,"procedure":"Elective laparoscopic ovarian cystectomy under general anesthesia","note":"ASA I"}'::jsonb,'{"bp":"118/72","hr":76,"spo2":99,"temp":36.6,"rr":14}'::jsonb,'["No chronic illness, no regular medication","General anesthesia with a muscle relaxant is planned","No known allergies"]'::jsonb,'[{"title":"Standards for Basic Anesthetic Monitoring","org":"American Society of Anesthesiologists (ASA)"}]'::jsonb,null,true)
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('perioperative-monitoring','s1',0,'mcq','Basic standard',null,'Which set represents the basic monitoring standard for a general anesthetic?','Monitoring',true,false,null,null,'Basic standards cover oxygenation (pulse oximetry), ventilation (capnography), circulation (ECG and blood pressure) and temperature when clinically relevant. Pulse oximetry alone shows oxygenation, not ventilation.','Oxygenation, ventilation, circulation, temperature. One monitor cannot cover all four.')
insert into public.questions (step_id,payload) select id, '{"options":[{"id":"a","text":"Pulse oximetry, ECG, non-invasive blood pressure and capnography, with temperature monitored when significant changes are anticipated"},{"id":"b","text":"ECG only"},{"id":"c","text":"Invasive arterial and central venous pressure for every patient"},{"id":"d","text":"Pulse oximetry only, because it shows both oxygenation and ventilation"}],"correct":"a"}'::jsonb from public.case_steps where case_id='perioperative-monitoring' and step_key='s1'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('perioperative-monitoring','s2',1,'equipment','Prepare the monitors',null,'Which items do you prepare?','Equipment Preparation',false,false,null,null,'Prepare the basic monitors plus a nerve stimulator because a muscle relaxant is planned. Invasive monitoring is reserved for patients or procedures that need it.','Match the monitors to the patient and the plan.')
insert into public.questions (step_id,payload) select id, '{"instruction":"Select the monitoring equipment to prepare for this patient.","items":[{"id":"e1","label":"Pulse oximeter probe","correct":true,"why":"Basic oxygenation monitor."},{"id":"e2","label":"ECG electrodes and leads","correct":true,"why":"Continuous ECG is a basic standard."},{"id":"e3","label":"Blood pressure cuff of the correct size","correct":true,"why":"A wrongly sized cuff gives wrong readings."},{"id":"e4","label":"Capnography sampling line","correct":true,"why":"Ventilation monitoring for general anesthesia."},{"id":"e5","label":"Temperature probe","correct":true,"why":"Temperature changes are expected during anesthesia."},{"id":"e6","label":"Peripheral nerve stimulator","correct":true,"why":"A muscle relaxant is planned, so neuromuscular function should be monitored."},{"id":"e7","label":"Pulmonary artery catheter","correct":false,"why":"Not indicated for this healthy patient."},{"id":"e8","label":"Central venous catheter set","correct":false,"why":"Not routinely indicated here."},{"id":"e9","label":"Invasive arterial line kit","correct":false,"why":"Not routinely indicated for an ASA I patient and this procedure."}]}'::jsonb from public.case_steps where case_id='perioperative-monitoring' and step_key='s2'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('perioperative-monitoring','s3',2,'mcq','Confirming ventilation','The patient has been intubated. Monitor: SpO₂ 99%, HR 72, BP 112/68, EtCO₂ 37 mmHg with a regular capnogram.','Which finding BEST confirms that the patient is being ventilated effectively?','Monitoring',false,false,'{"bp":"112/68","hr":72,"spo2":99,"etco2":37}'::jsonb,null,'Capnography directly shows exhaled CO₂ and therefore ventilation. SpO₂ can stay high for a while even when ventilation stops, especially after pre-oxygenation.','Capnography shows ventilation. SpO₂ lags behind.')
insert into public.questions (step_id,payload) select id, '{"options":[{"id":"a","text":"A regular capnogram waveform with a normal end-tidal CO₂ value"},{"id":"b","text":"Heart rate below 80"},{"id":"c","text":"SpO₂ of 99% alone"},{"id":"d","text":"Blood pressure has not changed"}],"correct":"a"}'::jsonb from public.case_steps where case_id='perioperative-monitoring' and step_key='s3'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('perioperative-monitoring','s4',3,'find-error','Monitoring set-up',null,'Review the current monitoring set-up. Which entries are problems?','Monitoring',true,false,null,null,'Muted alarms remove an important safety net, and placing the SpO₂ probe on the cuff arm causes repeated signal loss.','Alarms on, probe and cuff on different limbs.')
insert into public.questions (step_id,payload) select id, '{"instruction":"Select every entry that shows a monitoring problem.","items":[{"id":"c1","label":"ECG trace clear, leads secure","correct":false,"why":"Fine."},{"id":"c2","label":"Capnogram waveform present, EtCO₂ displayed","correct":false,"why":"Fine."},{"id":"c3","label":"Temperature probe placed, value displayed","correct":false,"why":"Fine."},{"id":"c4","label":"Blood pressure cuff size appropriate for arm","correct":false,"why":"Fine."},{"id":"c5","label":"Alarms muted to avoid disturbing the surgeon","correct":true,"why":"Alarms are a safety net. They must stay audible with appropriate limits."},{"id":"c6","label":"SpO₂ probe on the same arm as the blood pressure cuff (signal drops at every inflation)","correct":true,"why":"Cuff inflation interrupts the pulse oximeter signal. Use the other arm or another site."}]}'::jsonb from public.case_steps where case_id='perioperative-monitoring' and step_key='s4'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('perioperative-monitoring','s5',4,'mcq','How often?',null,'At minimum, how often should blood pressure and heart rate be evaluated during general anesthesia according to the ASA basic monitoring standard?','Documentation',false,false,null,null,'The ASA standard says arterial blood pressure and heart rate should be evaluated at least every five minutes during anesthesia. Institutional protocols may require more frequent checks.','Blood pressure and heart rate at least every 5 minutes.')
insert into public.questions (step_id,payload) select id, '{"options":[{"id":"a","text":"At least every 5 minutes"},{"id":"b","text":"Every 30 minutes"},{"id":"c","text":"Once at induction and once at emergence"},{"id":"d","text":"Only when an alarm sounds"}],"correct":"a"}'::jsonb from public.case_steps where case_id='perioperative-monitoring' and step_key='s5'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('perioperative-monitoring','s6',5,'branching','Falling blood pressure','45 minutes into surgery. The monitor now shows BP 82/48 and HR 112. The reading 5 minutes ago was 110/66.','What is your first action?','Emergency Response',true,false,'{"bp":"82/48","hr":112,"spo2":98,"etco2":34}'::jsonb,null,'A sharp fall in blood pressure with a rising heart rate is a significant change. Tell the anesthesiologist immediately while you verify the reading and look at possible causes.','Report significant changes early. Treatment decisions belong to the anesthesiologist.')
insert into public.questions (step_id,payload) select id, '{"options":[{"id":"a","text":"Inform the anesthesiologist immediately and help verify the reading (cuff, trace) while looking for causes such as bleeding or a change in position","score":100,"consequence":"The anesthesiologist is informed early and the reading is checked at the same time."},{"id":"b","text":"Recycle the cuff and wait for the next reading before telling anyone","score":40,"consequence":"Verifying is reasonable, but waiting to inform the anesthesiologist delays the response to a real trend."},{"id":"c","text":"Assume it is an artifact and ignore it","score":0,"consequence":"A clear change in trend, together with a rising heart rate, must not be ignored."},{"id":"d","text":"Give a medication to raise the pressure without instruction","score":0,"consequence":"Medication decisions belong to the anesthesiologist. Acting alone is unsafe."}]}'::jsonb from public.case_steps where case_id='perioperative-monitoring' and step_key='s6'
insert into public.cases (id,number,title,category,difficulty,duration_min,summary,scenario,objectives,patient,vitals,history,"references",scoring,published) values ('post-anesthesia-care',5,'Post-Anesthesia Care Unit','post-anesthesia','INTERMEDIATE',10,'Receive a patient in the PACU, run a safe handover and react to a drowsy patient with airway obstruction.','A patient has just arrived in the post-anesthesia care unit after general anesthesia. You are the recovery nurse. Prioritise airway and breathing, receive a structured handover, detect unsafe care and respond to a deteriorating patient.','["Prioritise actions on PACU arrival","Identify the essential elements of a handover","Recognise unsafe recovery care","Respond to airway obstruction in recovery"]'::jsonb,'{"sex":"Male","age":61,"procedure":"Elective hernia repair, general anesthesia (about 90 minutes)","note":"Extubated at end of surgery"}'::jsonb,'{"bp":"138/86","hr":88,"spo2":95,"temp":35.9,"rr":12}'::jsonb,'["Extubated in the operating room, transferred with oxygen","No known allergies","Analgesia plan as ordered by the anesthesiologist (see anesthesia record)"]'::jsonb,'[{"title":"Practice Guidelines for Postanesthetic Care","org":"American Society of Anesthesiologists (ASA)"}]'::jsonb,null,true)
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('post-anesthesia-care','s1',0,'sequence','Arrival priorities',null,'Arrange your actions when the patient arrives in the PACU.','Patient Assessment',true,false,null,null,'Airway and breathing come first. Monitors give objective data, then the handover fills in context. Symptoms are assessed next, and everything is documented and reassessed at regular intervals.','Airway and breathing first, then monitors, handover and full assessment.')
insert into public.questions (step_id,payload) select id, '{"items":[{"id":"i1","text":"Check airway patency and breathing, and give supplemental oxygen as ordered"},{"id":"i2","text":"Attach standard monitors and record initial vital signs"},{"id":"i3","text":"Receive a structured handover from the anesthesia team"},{"id":"i4","text":"Assess pain, nausea, temperature and the surgical site"},{"id":"i5","text":"Document and reassess at regular intervals"}]}'::jsonb from public.case_steps where case_id='post-anesthesia-care' and step_key='s1'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('post-anesthesia-care','s2',1,'mcq','Handover content',null,'Which information is essential in the handover from the anesthesia team?','Handover',true,false,null,null,'A good handover gives the recovery nurse what is needed to care for the patient safely: who the patient is, what happened, what to watch for and what the plan is.','Handover = who, what happened, what to watch for, what next.')
insert into public.questions (step_id,payload) select id, '{"options":[{"id":"a","text":"Identity, procedure, anesthetic technique, allergies, intra-operative events and the post-operative plan"},{"id":"b","text":"Only the surgeon''s name and the ward number"},{"id":"c","text":"Only the drugs that were given"},{"id":"d","text":"The patient''s insurance details"}],"correct":"a"}'::jsonb from public.case_steps where case_id='post-anesthesia-care' and step_key='s2'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('post-anesthesia-care','s3',2,'find-error','Recovery care review','Fifteen minutes after arrival, you review the recovery record and the bedside.','Which entries are unsafe?','Safety',true,false,'{"spo2":94,"rr":12}'::jsonb,null,'Snoring indicates partial upper-airway obstruction, and a patient recovering from anesthesia must never be left unobserved.','Snoring is an airway sign, not a sign of good sleep.')
insert into public.questions (step_id,payload) select id, '{"instruction":"Select every entry that shows unsafe care.","items":[{"id":"c1","label":"Oxygen supplied; SpO₂ monitored continuously","correct":false,"why":"Appropriate."},{"id":"c2","label":"Suction and bag-mask device available at the bedside","correct":false,"why":"Appropriate."},{"id":"c3","label":"Pain score documented using a numeric scale","correct":false,"why":"Appropriate."},{"id":"c4","label":"Temperature checked, warm blanket provided","correct":false,"why":"Appropriate for a mildly low temperature."},{"id":"c5","label":"Snoring respirations noted, no action taken because ''he is just sleeping''","correct":true,"why":"Snoring is a sign of partial airway obstruction and needs action."},{"id":"c6","label":"Patient left alone for 20 minutes while staff took a break","correct":true,"why":"Patients in recovery need continuous observation by a trained person."}]}'::jsonb from public.case_steps where case_id='post-anesthesia-care' and step_key='s3'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('post-anesthesia-care','s4',3,'branching','Drowsy and snoring','The patient is drowsy and making snoring sounds. SpO₂ has fallen to 90% and the respiratory rate is 8 per minute.','What do you do first?','Emergency Response',true,false,'{"spo2":90,"rr":8,"hr":96}'::jsonb,null,'Snoring with falling SpO₂ and a slow respiratory rate signals airway obstruction and inadequate ventilation. Open the airway, stimulate, confirm oxygen and get help.','Airway first: open it, give oxygen, call for help.')
insert into public.questions (step_id,payload) select id, '{"options":[{"id":"a","text":"Open the airway (chin lift or jaw thrust), stimulate the patient, make sure oxygen is delivered and call the anesthesiologist","score":100,"consequence":"The airway is opened, oxygen delivery is confirmed and help is on its way."},{"id":"b","text":"Increase the oxygen and observe quietly for another 15 minutes","score":40,"consequence":"Oxygen helps, but the cause is airway obstruction. Without opening the airway and calling for help, the patient may worsen."},{"id":"c","text":"Leave him to sleep: snoring is normal after anesthesia","score":0,"consequence":"Snoring with falling SpO₂ and slow breathing is not normal. The airway is at risk.","remedial":"r1"},{"id":"d","text":"Write the values in the record and continue paperwork","score":0,"consequence":"Documentation is important but cannot replace immediate action.","remedial":"r1"}]}'::jsonb from public.case_steps where case_id='post-anesthesia-care' and step_key='s4'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('post-anesthesia-care','r1',4,'mcq','Follow-up: no air movement','SpO₂ is 86%. The patient does not respond to your voice and you see chest effort but hear no air movement.','What now?','Emergency Response',false,true,'{"spo2":86,"rr":6,"hr":108}'::jsonb,null,'Chest effort without air movement means a complete airway obstruction. It is an emergency: call for help and support the airway and ventilation immediately.','Effort without air movement is an emergency. Call for help and support the airway.')
insert into public.questions (step_id,payload) select id, '{"options":[{"id":"a","text":"Call for urgent help and support airway and ventilation with a bag-mask and oxygen until the anesthesiologist arrives"},{"id":"b","text":"Wait five more minutes"},{"id":"c","text":"Move the patient to the ward"},{"id":"d","text":"Ask the family to wake him"}],"correct":"a"}'::jsonb from public.case_steps where case_id='post-anesthesia-care' and step_key='r1'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('post-anesthesia-care','s5',5,'mcq','Recovery scoring',null,'Which parameters make up the modified Aldrete score, commonly used to judge readiness to leave the PACU?','Patient Assessment',false,false,null,null,'The modified Aldrete score covers five areas: activity, respiration, circulation, consciousness and oxygen saturation. Many units also use additional criteria such as pain and nausea.','Aldrete: activity, respiration, circulation, consciousness, SpO₂.')
insert into public.questions (step_id,payload) select id, '{"options":[{"id":"a","text":"Activity, respiration, circulation, consciousness and oxygen saturation"},{"id":"b","text":"Heart rate, hemoglobin, glucose, sodium and potassium"},{"id":"c","text":"Pain score only"},{"id":"d","text":"Duration of surgery, type of surgery, surgeon and blood loss"}],"correct":"a"}'::jsonb from public.case_steps where case_id='post-anesthesia-care' and step_key='s5'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('post-anesthesia-care','s6',6,'equipment','Bedside readiness',null,'Which equipment do you prepare?','Equipment Preparation',false,false,null,null,'The bedside needs oxygen, suction, ventilation and airway equipment, monitors and a way to call for help. Operating-room items do not belong there.','Every recovery bed is ready for an airway emergency.')
insert into public.questions (step_id,payload) select id, '{"instruction":"Select the items that should be ready at every PACU bedside.","items":[{"id":"e1","label":"Oxygen source with delivery devices","correct":true,"why":"Supplemental oxygen is standard."},{"id":"e2","label":"Suction with catheters","correct":true,"why":"Needed for vomiting or secretions."},{"id":"e3","label":"Bag-valve-mask","correct":true,"why":"For assisted ventilation."},{"id":"e4","label":"Oral and nasal airways","correct":true,"why":"For airway obstruction."},{"id":"e5","label":"Continuous ECG, SpO₂ and blood pressure monitoring","correct":true,"why":"Early detection of deterioration."},{"id":"e6","label":"Emergency call system and access to a resuscitation trolley","correct":true,"why":"Help must be reachable quickly."},{"id":"e7","label":"Surgical instrument set","correct":false,"why":"Belongs in the operating room."},{"id":"e8","label":"Anesthesia gas vaporizer","correct":false,"why":"Part of the anesthesia machine, not the recovery bed."},{"id":"e9","label":"Sterile surgical drapes","correct":false,"why":"Not needed for routine recovery."}]}'::jsonb from public.case_steps where case_id='post-anesthesia-care' and step_key='s6'
insert into public.cases (id,number,title,category,difficulty,duration_min,summary,scenario,objectives,patient,vitals,history,"references",scoring,published) values ('anaphylaxis-emergency',6,'Emergency: Suspected Anaphylaxis','emergency','ADVANCED',10,'Recognise a severe allergic reaction under anesthesia and support the team through the first minutes.','General anesthesia has been induced and surgery has started. Minutes after a new intravenous drug is given, the patient''s condition changes quickly. You are the anesthesia nurse. Recognise the problem and support the anesthesiologist, who leads the emergency.','["Recognise the pattern of anaphylaxis under anesthesia","Order the first response actions","Prepare the right equipment","Communicate with the surgical team and document"]'::jsonb,'{"sex":"Female","age":35,"procedure":"Elective foot surgery under general anesthesia","note":"ASA I"}'::jsonb,'{"bp":"122/74","hr":80,"spo2":99,"temp":36.6,"etco2":36}'::jsonb,'["Healthy, no regular medication","No previous allergy reported","An intravenous antibiotic was started a few minutes ago"]'::jsonb,'[{"title":"Anaphylaxis guidance","org":"World Allergy Organization (WAO)"},{"title":"Emergency treatment of anaphylactic reactions","org":"Resuscitation Council UK"}]'::jsonb,null,true)
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('anaphylaxis-emergency','s1',0,'mcq','Recognise','Five minutes after an intravenous antibiotic was started, the monitor shows BP 70/38, HR 132 and SpO₂ 91%. Airway pressures have risen. You notice a red, blotchy rash on the patient''s chest and arms.','What is the most likely problem to consider first?','Emergency Recognition',true,false,'{"bp":"70/38","hr":132,"spo2":91,"etco2":26}'::jsonb,null,'Sudden hypotension, tachycardia, bronchospasm-like airway pressure rise and a skin rash shortly after a new drug strongly suggest anaphylaxis. Skin signs may be absent, so the pattern matters.','New drug plus sudden hypotension, airway signs and rash: think anaphylaxis.')
insert into public.questions (step_id,payload) select id, '{"options":[{"id":"a","text":"Anaphylaxis: a severe allergic reaction to a recently given drug"},{"id":"b","text":"Anesthesia that is too light"},{"id":"c","text":"A vasovagal reaction"},{"id":"d","text":"Hypothermia"}],"correct":"a"}'::jsonb from public.case_steps where case_id='anaphylaxis-emergency' and step_key='s1'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('anaphylaxis-emergency','s2',1,'sequence','First actions',null,'Arrange the first-response actions in a logical order.','Emergency Response',true,false,null,null,'The trigger is stopped and help is called immediately. Oxygenation and airway support follow, then epinephrine and circulatory support as directed by the anesthesiologist. Documentation is completed as soon as it is safe. Always follow your institution''s protocol.','Stop the trigger, call for help, oxygenate, then support the anesthesiologist''s treatment.')
insert into public.questions (step_id,payload) select id, '{"items":[{"id":"i1","text":"Stop the suspected trigger (for example the antibiotic infusion)"},{"id":"i2","text":"Call for help and alert the whole team"},{"id":"i3","text":"Give 100% oxygen and support the airway and ventilation"},{"id":"i4","text":"Prepare epinephrine according to institutional protocol, as directed by the anesthesiologist"},{"id":"i5","text":"Support circulation: large-bore IV access and IV fluids as directed"},{"id":"i6","text":"Document the timeline and suspected agent; collect samples if requested"}]}'::jsonb from public.case_steps where case_id='anaphylaxis-emergency' and step_key='s2'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('anaphylaxis-emergency','s3',2,'equipment','Prepare for treatment',null,'Which items help the team in this emergency?','Equipment Preparation',true,false,null,null,'Prepare epinephrine per protocol, fluids and access, airway and ventilation equipment, and emergency resuscitation equipment. The suspected drug must not be given again.','Remove the trigger, prepare airway, circulation and rescue equipment.')
insert into public.questions (step_id,payload) select id, '{"instruction":"Select what should be prepared or brought to the bedside.","items":[{"id":"e1","label":"Epinephrine available according to protocol, ready for the anesthesiologist","correct":true,"why":"First-line drug in anaphylaxis. The anesthesiologist decides on use."},{"id":"e2","label":"Large-bore IV cannula and IV fluid sets","correct":true,"why":"Circulatory support."},{"id":"e3","label":"Suction and airway equipment ready","correct":true,"why":"The airway may need rapid support."},{"id":"e4","label":"Bag-valve-mask with 100% oxygen","correct":true,"why":"Ventilation and oxygenation backup."},{"id":"e5","label":"Defibrillator and resuscitation trolley nearby","correct":true,"why":"Cardiac arrest is a risk if the patient deteriorates."},{"id":"e6","label":"The remaining antibiotic, to finish the infusion","correct":false,"why":"The suspected trigger must not be given again."},{"id":"e7","label":"Sedative premedication","correct":false,"why":"Not part of the emergency response."},{"id":"e8","label":"Tourniquet","correct":false,"why":"Not needed for this emergency."},{"id":"e9","label":"Urinary catheter set","correct":false,"why":"Not a first-response item."}]}'::jsonb from public.case_steps where case_id='anaphylaxis-emergency' and step_key='s3'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('anaphylaxis-emergency','s4',3,'branching','Communication','The surgeon says: ''We are almost finished with the incision. Can we continue?''','How do you respond?','Communication',true,false,null,null,'In an emergency the whole team must share the same information. The anesthesiologist leads the medical response, and decisions about the surgery are made jointly.','Brief, clear, factual communication to the whole team.')
insert into public.questions (step_id,payload) select id, '{"options":[{"id":"a","text":"State clearly that the patient is unstable with suspected anaphylaxis, that the anesthesiologist is leading, and that continuing is a team decision once the patient is stabilised","score":100,"consequence":"The surgeon has the key facts and the decision is made together with the anesthesiologist."},{"id":"b","text":"Reassure the surgeon and let them carry on as normal","score":0,"consequence":"Continuing without a shared decision puts an unstable patient at risk."},{"id":"c","text":"Say nothing and leave communication to others","score":40,"consequence":"Silence leaves the surgeon uninformed. Clear, brief communication is part of your role."},{"id":"d","text":"Ask the surgeon to hurry so anesthesia time is shorter","score":0,"consequence":"Speeding up surgery does not treat the emergency and adds risk."}]}'::jsonb from public.case_steps where case_id='anaphylaxis-emergency' and step_key='s4'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('anaphylaxis-emergency','s5',4,'mcq','After stabilisation','The patient is stabilised and will be moved to a monitored area.','What follow-up is essential?','Documentation',true,false,'{"bp":"108/64","hr":96,"spo2":97,"etco2":34}'::jsonb,null,'Symptoms can recur, so close monitoring continues. The suspected agent and reaction must be recorded and communicated so the patient is protected in future and can be evaluated for allergy.','Document the suspected agent, hand over clearly, keep watching.')
insert into public.questions (step_id,payload) select id, '{"options":[{"id":"a","text":"Document the reaction and suspected agent clearly, hand over to the receiving team, keep close monitoring because symptoms can return, and make sure allergy evaluation is arranged"},{"id":"b","text":"No follow-up is needed once the vital signs are normal"},{"id":"c","text":"Tell only the relatives, not the record"},{"id":"d","text":"Leave the event out of the record so other staff are not alarmed"}],"correct":"a"}'::jsonb from public.case_steps where case_id='anaphylaxis-emergency' and step_key='s5'
